  if(camH>1.25){ const k=Math.min(1,(camH-1.25)/.45), hx=W-56, hy=H-(130*k)+(reload>0?60:0); cx.fillStyle=FR[me].c; cx.beginPath(); cx.moveTo(hx-22,hy+14); cx.lineTo(hx+16,hy+18); cx.lineTo(W+30,H+40); cx.lineTo(W-90,H+40); cx.closePath(); cx.fill(); cx.fillStyle='#13233A'; cx.beginPath(); cx.arc(hx-2,hy+10,20,0,7); cx.fill(); if(reload<=0) ball(hx-2,hy-6,20); }
