    const x0=.32,y0=camH-.3,z0=HAND_Z; cx.fillStyle='rgba(19,35,58,.5)'; for(let k=1;k<12;k++){ const tt=k/12*FLIGHT; const x=x0+(tx-x0)*tt/FLIGHT, z=z0+(ZO-z0)*tt/FLIGHT, y=y0+((ty-y0+.5*G*FLIGHT*FLIGHT)/FLIGHT)*tt-.5*G*tt*tt; const [Xa,Ya,sa]=P(x,y,z); if(z<ZW+.2) continue; cx.beginPath(); cx.arc(Xa,Ya,Math.max(1.5,.03*sa),0,7); cx.fill(); }
