  const hy=-1.62*s; cx.fillStyle='#F2D2BE'; cx.beginPath(); cx.arc(0,hy,.22*s,0,7); cx.fill();
  cx.fillStyle='#13233A'; cx.fillRect(-.09*s,hy-.03*s,.05*s,.05*s); cx.fillRect(.05*s,hy-.03*s,.05*s,.05*s);
